import { Component, input } from '@angular/core';

/** A period's line of the classic summary: its due-total counting each claim by its status now. */
export interface ClassicPeriodSummary {
  name: string;
  dueTotal: string;
}

// The sheet summed up the classic way: per period by each claim's status now, and the due-total untrimmed.
@Component({
  selector: 'app-classic-summary-panel',
  template: `
    <section aria-labelledby="classic-summary-heading" data-testid="classic-summary">
      <h2 id="classic-summary-heading">Classic summary</h2>
      <table>
        <caption>By period</caption>
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due</th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'classic-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
            </tr>
          }
        </tbody>
      </table>
      <dl>
        <dt>Due, untrimmed</dt>
        <dd data-testid="classic-due-total">{{ dueTotal() }}</dd>
      </dl>
    </section>
  `,
})
export class ClassicSummaryPanel {
  readonly periods = input.required<ClassicPeriodSummary[]>();
  readonly dueTotal = input.required<string>();
}
EOF
python3 - <<'EOF'
p='features/people/people-list.ts'
s=open(p).read()
s=s.replace("import { HeaderCounters } from '../summary/header-counters';","import { HeaderCounters } from '../summary/header-counters';\nimport { ClassicPeriodSummary, ClassicSummaryPanel } from '../summary/classic-summary-panel';",1)
s=s.replace("SummaryPanel, HeaderCounters,","SummaryPanel, ClassicSummaryPanel, HeaderCounters,",1)
s=s.replace("""        [voidReasons]="voidReasonSummary()" />
""","""        [voidReasons]="voidReasonSummary()" />
      <app-classic-summary-panel [periods]="classicPeriodSummary()" [dueTotal]="classicDueTotal()" />
""",1)
anchor="  /** Per status: how many claims on the sheet have it. */"
add='''  /** Per period, as listed: the due figures of the claims whose due-by falls in it that count by
   *  their status now, skipping those with no due (a closed period shows the figure fixed when it
   *  closed). */
  protected readonly classicPeriodSummary = computed((): ClassicPeriodSummary[] => {
    const figures = new Map<number, string[]>();
    for (const c of this.claims()) {
      const period = periodOf(this.periods(), c.dueBy);
      const person = this.byId().get(c.personId);
      if (period === undefined || person === undefined) continue;
      if (!countsLive(c, person, this.session.today())) continue;
      const d = claimDue(c, this.rates(), gradeOn(person.grades, c.date), this.floor(), this.lateness());
      if (d !== null) figures.set(period.id, [...(figures.get(period.id) ?? []), d]);
    }
    return this.periods().map((p) => ({
      name: p.name,
      dueTotal: p.closed || p.softClosed
        ? (this.periodDueTotals().get(p.id) ?? '0.00')
        : sumAmounts(figures.get(p.id) ?? []),
    }));
  });
  /** The sheet's due-total with no trimming: everyone's due-total added up, skipping those that are n/a. */
  protected readonly classicDueTotal = computed(() =>
    sumAmounts(this.people().map((p) => this.dueOf(p)).filter((d): d is string => d !== null)),
  );
'''
assert anchor in s
s=s.replace(anchor,add+anchor,1)
open(p,'w').write(s)
EOF
